    const nA = +$('gfNA').value, sy = +$('gfSyn').value, mv = +$('gfMv').value, nI = +$('gfNI').value;
    ['gfNA', 'gfSyn', 'gfMv', 'gfNI'].forEach(id => $(id + '-o').textContent = $(id).value);
    const P = gfSpikeProb(nA, sy, mv, nI, 0.5);
    const [x, W, H] = gfCanvas('gfProb'), L = 46, B = H - 30, T = 14;
    x.strokeStyle = '#e6d8c8'; for (let k = 0; k <= 4; k++) { const y = B - (B - T) * k / 4; x.beginPath(); x.moveTo(L, y); x.lineTo(W - 10, y); x.stroke(); x.fillStyle = '#6f4c27'; x.fillText(k * 25 + '%', 8, y + 4); }
    x.strokeStyle = '#a62962'; x.lineWidth = 2; x.beginPath();
    for (let n = 0; n <= 8; n += 0.1) { const X = L + (W - L - 10) * n / 8, Y = B - (B - T) * gfSpikeProb(n, sy, mv, nI, 0.5); n === 0 ? x.moveTo(X, Y) : x.lineTo(X, Y); } x.stroke(); x.lineWidth = 1;
    const X0 = L + (W - L - 10) * nA / 8, Y0 = B - (B - T) * P; x.fillStyle = '#a62962'; x.beginPath(); x.arc(X0, Y0, 5, 0, 7); x.fill();
    x.fillStyle = '#3d6a8c'; [[0, 0.2], [8, 0.98]].forEach(([n, p]) => { const X = L + (W - L - 10) * n / 8, Y = B - (B - T) * p; x.fillRect(X - 4, Y - 4, 8, 8); });
    x.fillStyle = '#3a2a1c'; x.fillText('active Axc neurons →', L, H - 8); x.fillText('■ in vivo (no light ≈ 20 %, light ≈ 100 %)', W - 250, H - 8);
    $('gfPOut').innerHTML = `<p>P(GF spike) = <b>${(100 * P).toFixed(0)}%</b>. Summed axo-axonic depolarisation: ${(nA * sy * mv).toFixed(2)} mV excitatory, ${(nI * 0.5).toFixed(1)} mV inhibitory.</p><p class="muted">With 8 Axc cells and ${sy} synapses each, the in-vivo jump to ~100 % needs about ${(2.9 / (8 * sy)).toFixed(3)} mV per synapse at the spike zone in this toy.</p>`;
