const CCF_REGCOL = { root: [0.55, 0.47, 0.40], HPF: [0.65, 0.16, 0.38], CA1: [0.65, 0.16, 0.38], CA2: [0.85, 0.45, 0.25], CA3: [0.24, 0.42, 0.55], DG: [0.44, 0.30, 0.15], SUB: [0.48, 0.60, 0.29], ENTl: [0.82, 0.54, 0.18], ENTm: [0.90, 0.68, 0.30], MS: [0.55, 0.30, 0.65], TH: [0.24, 0.55, 0.50], Isocortex: [0.62, 0.62, 0.70], CB: [0.70, 0.55, 0.40], STR: [0.40, 0.48, 0.70], OLF: [0.70, 0.70, 0.45] };
