        <div class="control-row"><label>View</label><div class="lab-actions ml-seg"><button class="secondary" data-wbv="lat">Side</button><button class="secondary" data-wbv="dor" aria-pressed="true">Top</button><button class="secondary" data-wbv="fro">Front</button></div></div>
