  document.querySelectorAll('[data-wbv]').forEach(b => b.onclick = () => { [S.yaw, S.pitch] = b.dataset.wbv === 'lat' ? [0, 0.001] : b.dataset.wbv === 'dor' ? [0, -Math.PI / 2 + 0.001] : [Math.PI / 2, 0.001]; document.querySelectorAll('[data-wbv]').forEach(x => x.setAttribute('aria-pressed', x === b)); draw(); });
