// Data: bapdata.js (lazy) = BAP_DATA {cellId: {kscale: {sec:[[dist, peak]|null], soma_peak, apical_bins}}, _validation}
// ============================================================================
const BAP_STORE = { d: null, loading: false };
window.ngBapData = d => { BAP_STORE.d = d; };
const BAP_CELLS = [['ca1-a', 'CA1 pyramidal mpg141209_A (Migliore 2018)', 'mpg141209_A'], ['ca1-b', 'CA1 pyramidal mpg141208_B (Migliore 2018)', 'mpg141208_B'], ['ca1-jarsky', 'CA1 pyramidal (Jarsky 2005)', 'Jarsky 2005'], ['ca1-5038804', 'CA1 pyramidal n5038804 (Duke–Southampton)', 'n5038804'], ['pyr-nmo-163712', 'CA1 pyramidal, SEU–Allen (mouse)', 'SEU–Allen mouse']];
const BAP_LCOL = ['#a62962', '#3d6a8c', '#d08a2e', '#2f7d5b', '#6f4c27', '#7a3fa6'];
function renderActiveDendrites() {
  document.title = 'Active dendrites in real cells · Real biology';
  const need = [];
  if (!BAP_STORE.d) need.push('bapdata.js');
  if (!NM_STORE.loaded) need.push('atlasdata.js');
  if (need.length) {
    $('lesson').innerHTML = '<div class="hero"><h1>Active dendrites in real cells</h1><p>Loading NEURON results…</p></div>';
    if (!BAP_STORE.loading) { BAP_STORE.loading = true; let left = need.length; const done = () => { if (--left === 0) { BAP_STORE.loading = false; if (/active-dendrites/.test(ngPath())) renderActiveDendrites(); } };
      need.forEach(f => f === 'atlasdata.js' ? ngLoadAtlasData(done) : (() => { const sc = document.createElement('script'); sc.src = f; sc.onload = done; sc.onerror = done; document.head.appendChild(sc); })()); }
    return;
  }
  const D = BAP_STORE.d, V = D._validation, cells = BAP_CELLS.filter(([id]) => D[id]);
  $('lesson').innerHTML = bioHead('Active dendrites in real cells', 'REAL BIOLOGY · NEURON · ' + cells.length + ' RECONSTRUCTED CA1 CELLS · MIGLIORE ET AL. 2005 CHANNELS', 'A somatic spike travels back into the dendrites (a back-propagating action potential, bAP). How far it gets depends on sodium channels, A-type potassium channels and the shape of the tree. Here the same channel model runs on five real CA1 pyramidal cells, so you can separate the effect of morphology from the effect of channels.')
    + `<nav class="page-jumps"><a href="#bap-view">bAP map</a><a href="#bap-curves">Compare cells</a><a href="#bap-valid">Validation</a><a href="#bap-uth">Model details</a><a href="#bap-research">Research questions</a></nav>
    <section class="lesson-section lab" id="bap-view"><p class="eyebrow">01 · Predict → change → observe</p><h2>Where does the spike reach?</h2>
      <p>Predict first: if you <b>halve</b> the A-type K⁺ density, do distal dendrites see a bigger or smaller bAP? Does the answer depend on the cell?</p>
      <div class="nv-wrap"><div class="at-stage"><canvas id="bapCv" class="nv-canvas" style="height:520px" aria-label="Neuron coloured by bAP peak amplitude"></canvas></div>
      <div class="lab-controls nv-controls">
        <div class="control-row"><label for="bapCell">Cell</label><select id="bapCell">${cells.map(([id, l]) => `<option value="${id}">${l}</option>`).join('')}</select></div>
        <div class="control-row"><label>A-type K⁺ density</label><div class="lab-actions ml-seg">${['0.5', '1', '1.5'].map(k => `<button class="secondary" data-bk="${k === '1' ? '1.0' : k}" aria-pressed="${k === '1'}">${k}×</button>`).join('')}</div></div>
        <div id="bapScale" class="bap-scale"></div>
        <div id="bapOut" class="ml-fp"></div>
        <p class="muted">Colour = peak membrane depolarisation (mV above rest) reached during the bAP, computed by NEURON for every branch. Drag to rotate.</p></div></div></section>
    <section class="lesson-section" id="bap-curves"><p class="eyebrow">02 · Compare</p><h2>Same channels, different shapes</h2>
      <p>The curves show the mean bAP peak in apical dendrites as a function of path distance from the soma (50 µm bins), one line per cell, at the A-type density chosen above. The channel densities and gradients are identical, so all the differences between lines come from morphology.</p>
      <canvas id="bapPlot" class="uth-plot" style="height:320px" aria-label="bAP amplitude versus distance for each cell"></canvas><div id="bapKey" class="uth-key"></div>
      <div id="bapTable"></div>
      <h3>The switch: distal bAP vs A-type density</h3>
      <p>Each line shows one cell's mean bAP peak at 350–450 µm as the A-type K⁺ density is scaled from 0.25× to 2×. Every cell flips from <b>strong</b> to <b>weak</b> back-propagation over a narrow range, but the flip happens at a different density for each morphology. This is one candidate explanation for the strong/weak dichotomy seen experimentally.</p>
      <canvas id="bapSweep" class="uth-plot" style="height:300px" aria-label="Distal bAP versus A-type density"></canvas><div id="bapSweepTxt" class="ml-fp"></div></section>
    <section class="lesson-section" id="bap-valid"><p class="eyebrow">03 · Behind the black box</p><h2>Does this pipeline reproduce the original model?</h2>
      <p>Before running the channel model on other cells, I re-ran the authors’ own hoc code (ModelDB 55035, Fig. 2A, neuron n5038804) headless in NEURON. I then ran this page’s pipeline on the same neuron after it had been converted, thinned and given a cylindrical soma. Mean bAP peak per 100 µm of path distance:</p>
      <table class="gf-tab"><tr><th>Distance from soma</th>${V.bins_um.map(b => `<th>${b}–${b + 100} µm</th>`).join('')}</tr><tr><td>Original hoc (authors’ code)</td>${V.original_hoc_mV.map(v => `<td>${v ?? '—'} mV</td>`).join('')}</tr><tr><td>This page’s pipeline</td>${V.this_pipeline_mV.map(v => `<td>${v ?? '—'} mV</td>`).join('')}</tr></table>
      <p class="uth-now">Agreement is within about 3 mV up to 300 µm. Beyond that, the converted cell attenuates more: 34 vs 47 mV at 300–400 µm, and 8 vs 14 mV past 400 µm. Likely causes are the point thinning (≥3 µm), the cylindrical soma in place of the traced soma, and binning over fewer distal sections. Treat distal values as about ±10 mV.</p></section>
    <section class="lesson-section" id="bap-uth"><p class="eyebrow">04 · Model details</p><h2>Under the hood</h2>
      <details class="uth" open><summary><span>Under the hood</span> channels, gradients, stimulus and numerics</summary><div class="uth-grid">
        <section><h4>Membrane</h4><p>\\(C_m\\frac{dV}{dt} = -g_{pas}(V-E_{pas}) - \\bar g_{Na}m^3h\\,(V-E_{Na}) - \\bar g_{Kdr}n^4(V-E_K) - \\bar g_{KA}\\,a\\,b\\,(V-E_K) - \\bar g_h\\,l\\,(V-E_h) + I\\)</p>
        <p>R<sub>m</sub> = 28 kΩ·cm², C<sub>m</sub> = 1 µF/cm², R<sub>a</sub> = 150 Ω·cm (axon 50). E<sub>Na</sub> = 55, E<sub>K</sub> = −90, E<sub>h</sub> = −30 mV. Temperature 35 °C. E<sub>pas</sub> is set per segment so that every compartment starts at steady state at −65 mV, as in the original code.</p></section>
        <section><h4>Distributions (d = path distance from soma)</h4><ul class="skill-tips"><li>Na⁺ (na3): 25 mS/cm², uniform in soma and dendrites; axon nax 5× higher.</li><li>K<sub>dr</sub>: 10 mS/cm², uniform.</li><li>A-type K⁺: proximal form (kap) for d ≤ 100 µm and distal form (kad) beyond, both \\(30\\,(1+d/100)\\) mS/cm² × the scale you choose.</li><li>I<sub>h</sub>: \\(0.05\\,(1+3d/100)\\) mS/cm², with half-activation −73 mV proximally and −81 mV distally.</li></ul></section>
        <section><h4>Stimulus & numerics</h4><p>Somatic current step of 2.5 nA for 1.5 ms (one spike). Variable-step CVODE, 20 ms run, d_λ = 0.1 at 50 Hz for segmentation. Peak V per segment is recorded with the authors’ <code>ds</code> mechanism. Cells without a usable traced axon get a standard 200 µm, 1 µm-diameter axon carrying the axonal channels. Long-range MouseLight and SEU–Allen axons are replaced by that stub so they do not dominate run time.</p></section>
        <section><h4>Limits</h4><p>This is one published parameter set, tuned to one cell, applied to others. Real cells vary in channel density, spine density (spines add membrane and are not modelled here) and dendritic Na⁺ inactivation during trains. The point is the <i>relative</i> effect of morphology, not exact millivolts.</p>
        <p class="uth-now"><b>Not a subthreshold model.</b> I also ran 0.5–20 Hz ZAP (chirp) currents to look for I<sub>h</sub> resonance. At rest this channel set has a somatic input impedance of only about 10–15 MΩ (n5038804), well below typical CA1 recordings, because the large A-type and K<sub>dr</sub> conductances are partly open at −65 mV. Its impedance profile shows no theta resonance. So use this model for bAPs and a resonance-tuned model (for example your two-compartment CA1 model, or I<sub>h</sub>/M-current models fitted to impedance data) for theta questions.</p></section></div></details></section>
    <section class="lesson-section" id="bap-research"><p class="eyebrow">05 · Research questions</p><h2>What could you test with this?</h2>
      <ul class="skill-tips"><li><b>Strong vs weak propagation.</b> Golding, Kath & Spruston (2001) found that distal bAP amplitude in CA1 is bimodal across cells. Does any of these morphologies switch between regimes with a modest A-type change, while others do not?</li>
      <li><b>Obliques vs trunk.</b> Migliore et al. (2005) showed that local oblique geometry shapes propagation. Colour the map and compare obliques with trunk segments at the same distance.</li>
      <li><b>Alzheimer’s link.</b> A-type K⁺ (Kv4.2) loss and dendritic hyperexcitability are reported in AD models (for example tau-dependent Kv4.2 depletion; <a href="https://pubmed.ncbi.nlm.nih.gov/?term=Tau-dependent+Kv4.2+depletion+and+dendritic+hyperexcitability+in+a+mouse+model+of+Alzheimer%27s+disease" target="_blank" rel="noopener">Hall et al. 2015</a>). Scaling A-type to 0.5× gives a first-pass prediction of how much further bAPs would invade, and so how plasticity (which needs bAP–EPSP coincidence) might change.</li>
      <li><b>Your resonance project.</b> The I<sub>h</sub> gradient is the same one that sets dendritic theta resonance. A next step is to run chirp-current impedance profiles on these five cells.</li></ul></section>
    <section class="lesson-section" id="code"><p class="eyebrow">06 · Do it in Python</p><h2>Run a bAP on any reconstruction in NEURON</h2><div class="code-toolbar"><span>Python 3 · neuron</span></div><pre><code># pip install neuron ; git clone https://github.com/ModelDBRepository/55035 ; cd 55035 ; nrnivmodl .
from neuron import h
h.load_file("stdrun.hoc"); h.load_file("import3d.hoc")
cell = h.Import3d_SWC_read(); cell.input("cell.swc")          # any CA1 pyramidal SWC from NeuroMorpho
h.Import3d_GUI(cell, False).instantiate(None)
soma = h.soma[0]; h.distance(0, 0.5, sec=soma); h.celsius = 35
for sec in h.allsec():
    sec.insert("pas"); sec.g_pas = 1 / 28000; sec.e_pas = -65; sec.Ra = 150; sec.cm = 1
    sec.nseg = 1 + 2 * int(sec.L / 20)
    for m in ("na3", "kdr", "kap", "kad", "hd", "ds"): sec.insert(m)
    for seg in sec:
        d = h.distance(seg.x, sec=sec)
        seg.gbar_na3, seg.gkdrbar_kdr = 0.025, 0.01
        seg.ghdbar_hd = 0.00005 * (1 + 3 * d / 100)
        ka = 0.03 * (1 + d / 100)                      # A-type gradient; scale this to find the strong/weak switch
        seg.gkabar_kad, seg.gkabar_kap = (ka, 0) if d > 100 else (0, ka)
stim = h.IClamp(soma(0.5)); stim.amp, stim.dur, stim.delay = 2.5, 1.5, 1
h.finitialize(-65); h.continuerun(20)
apical = [(h.distance(0.5, sec=s), s(0.5).vmax_ds + 65) for s in h.allsec() if "apic" in s.name()]
for d, v in sorted(apical)[::10]:
    print(f"{d:6.0f} µm  {v:5.1f} mV")</code></pre>
      <p class="muted">This short version skips the steady-state E<sub>pas</sub> correction and the axon. The notebook <b>“Active dendrites: bAP”</b> has the full validated pipeline, including the re-run of the authors’ Fig. 2A.</p></section>
    <section class="lesson-section reading"><p class="eyebrow">Sources</p><ol class="gf-refs">
      <li><a href="https://pubmed.ncbi.nlm.nih.gov/?term=Signal+propagation+in+oblique+dendrites+of+CA1+pyramidal+cells" target="_blank" rel="noopener">Migliore M, Ferrante M, Ascoli GA (2005) Signal propagation in oblique dendrites of CA1 pyramidal cells. J Neurophysiol 94:4145–4155 (ModelDB 55035) ↗</a></li>
      <li><a href="https://pubmed.ncbi.nlm.nih.gov/?term=Dichotomy+of+action-potential+backpropagation+in+CA1+pyramidal+neuron+dendrites" target="_blank" rel="noopener">Golding NL, Kath WL, Spruston N (2001) Dichotomy of action-potential backpropagation in CA1 pyramidal neuron dendrites. J Neurophysiol 86:2998–3010 ↗</a></li>
      <li><a href="https://pubmed.ncbi.nlm.nih.gov/?term=K%2B+channel+regulation+of+signal+propagation+in+dendrites+of+hippocampal+pyramidal+neurons" target="_blank" rel="noopener">Hoffman DA, Magee JC, Colbert CM, Johnston D (1997) K⁺ channel regulation of signal propagation in dendrites of hippocampal pyramidal neurons. Nature 387:869–875 ↗</a></li>
      <li><a href="https://pubmed.ncbi.nlm.nih.gov/?term=Action+potential+initiation+and+backpropagation+in+neurons+of+the+mammalian+CNS" target="_blank" rel="noopener">Stuart G, Spruston N, Sakmann B, Häusser M (1997) Action potential initiation and backpropagation in neurons of the mammalian CNS. Trends Neurosci 20:125–131 ↗</a></li></ol></section>`;
  typeset(); bapInit(D, cells);
}
function bapInit(D, cells) {
  const S = { cell: cells[0][0], k: '1.0', yaw: 0, pitch: 0 };
  const findMeta = id => ATLAS.find(m => m.id === id);
  const col = v => v == null ? '#ddd' : `hsl(${Math.round(250 - 250 * Math.min(1, Math.max(0, v) / 100))} 70% 45%)`;
  const draw = () => {
    const m = findMeta(S.cell); if (!m) return; const c = atlasCell(m), G = cellGeometry(c), R = D[S.cell][S.k], map = m._orig;
    atDraw($('bapCv'), c, G, { yaw: S.yaw, pitch: S.pitch, axon: false, bar: true, segCol: (i, s) => { const orig = map ? map[s.sec] : s.sec, x = R.sec[orig]; return x ? col(x[1]) : '#ccc'; } });
  };
  const plot = () => {
    const [x, W, H] = gfCanvas('bapPlot'), L = 46, B = H - 32, T = 10, Rr = W - 12, dmax = 700;
    x.strokeStyle = '#e6d8c8'; for (let v = 0; v <= 100; v += 25) { const y = B - (B - T) * v / 100; x.beginPath(); x.moveTo(L, y); x.lineTo(Rr, y); x.stroke(); x.fillStyle = '#6f4c27'; x.font = '11px system-ui'; x.fillText(v + ' mV', 4, y + 4); }
    for (let d = 0; d <= dmax; d += 100) { const X0 = L + (Rr - L) * d / dmax; x.fillText(d, X0 - 8, H - 16); } x.fillText('path distance from soma (µm)', L, H - 2);
    cells.forEach(([id], i) => { const b = D[id][S.k].apical_bins; x.strokeStyle = BAP_LCOL[i]; x.lineWidth = id === S.cell ? 3 : 1.4; x.beginPath(); let st = false; b.forEach(([lo, v]) => { if (v == null) return; const X0 = L + (Rr - L) * (lo + 25) / dmax, Y0 = B - (B - T) * v / 100; st ? x.lineTo(X0, Y0) : x.moveTo(X0, Y0); st = true; }); x.stroke(); });
    x.lineWidth = 1; $('bapKey').innerHTML = cells.map(([id, l], i) => `<span><i style="background:${BAP_LCOL[i]}"></i>${l}</span>`).join('');
    const at = (b, d) => { const r = b.find(q => q[0] === d); return r && r[1] != null ? r[1].toFixed(0) + ' mV' : '—'; };
    $('bapTable').innerHTML = `<div class="ml-tablewrap"><table class="ml-table bap-tab"><thead><tr><th>Cell</th><th>Soma peak</th><th>100–150 µm</th><th>250–300 µm</th><th>400–450 µm</th><th>Change at 400 µm, A-type 0.5× vs 1×</th></tr></thead><tbody>${cells.map(([id, l]) => { const b = D[id][S.k].apical_bins, lo = D[id]['0.5'].apical_bins, hi = D[id]['1.0'].apical_bins; const a = (lo.find(q => q[0] === 400) || [])[1], c = (hi.find(q => q[0] === 400) || [])[1]; return `<tr><td>${l}</td><td>${D[id][S.k].soma_peak} mV</td><td>${at(b, 100)}</td><td>${at(b, 250)}</td><td>${at(b, 400)}</td><td>${a != null && c != null ? (a - c >= 0 ? '+' : '') + (a - c).toFixed(0) + ' mV' : '—'}</td></tr>`; }).join('')}</tbody></table></div>`;
  };
  const out = () => {
    const r = D[S.cell][S.k], b = r.apical_bins.filter(q => q[1] != null), far = b[b.length - 1];
    $('bapOut').innerHTML = `<p>Soma: <b>${r.soma_peak} mV</b> spike. Apical bAP falls to <b>${far ? far[1].toFixed(0) : '—'} mV</b> by ${far ? far[0] + 25 : '—'} µm.</p>`;
    $('bapScale').innerHTML = `<span>0</span><i></i><span>100 mV</span>`;
  };
  const sweep = () => {
    const W0 = D._sweep, ks = W0.kscale, [x, W, H] = gfCanvas('bapSweep'), L = 46, B = H - 32, T = 10, Rr = W - 12, kx = k => L + (Rr - L) * (k - ks[0]) / (ks[ks.length - 1] - ks[0]);
    x.strokeStyle = '#e6d8c8'; x.font = '11px system-ui'; for (let v = 0; v <= 100; v += 25) { const y = B - (B - T) * v / 100; x.beginPath(); x.moveTo(L, y); x.lineTo(Rr, y); x.stroke(); x.fillStyle = '#6f4c27'; x.fillText(v + ' mV', 4, y + 4); }
    [0.25, 0.5, 1, 1.5, 2].forEach(k => { x.fillText(k + '×', kx(k) - 8, H - 16); }); x.fillText('A-type K⁺ density (× published value)', L, H - 2);
    const sw = [];
    cells.forEach(([id, l, sh], i) => { const v = W0.distal_350_450[id]; if (!v) return; x.strokeStyle = BAP_LCOL[i]; x.lineWidth = id === S.cell ? 3 : 1.4; x.beginPath(); v.forEach((q, j) => { if (q == null) return; const X0 = kx(ks[j]), Y0 = B - (B - T) * q / 100; j ? x.lineTo(X0, Y0) : x.moveTo(X0, Y0); }); x.stroke();
      let best = 0, at = null; for (let j = 1; j < v.length; j++) if (v[j - 1] != null && v[j] != null && v[j - 1] - v[j] > best) { best = v[j - 1] - v[j]; at = (ks[j - 1] + ks[j]) / 2; } sw.push([sh, at, best]); });
    x.lineWidth = 1; x.strokeStyle = '#999'; x.setLineDash([4, 4]); x.beginPath(); x.moveTo(kx(1), T); x.lineTo(kx(1), B); x.stroke(); x.setLineDash([]);
    $('bapSweepTxt').innerHTML = '<p><b>Switch point</b> (steepest drop) per cell: ' + sw.map(([l, a, b]) => `${l}: <b>${a.toFixed(2)}×</b> (−${b.toFixed(0)} mV)`).join(' · ') + '. Dashed line = published density.</p>';
  };
  const all = () => { draw(); plot(); out(); sweep(); };
  $('bapCell').onchange = e => { S.cell = e.target.value; S.yaw = 0; all(); };
  document.querySelectorAll('[data-bk]').forEach(b => b.onclick = () => { S.k = b.dataset.bk; document.querySelectorAll('[data-bk]').forEach(o => o.setAttribute('aria-pressed', o === b)); all(); });
  let drag = null; const cv = $('bapCv');
  cv.onpointerdown = e => { drag = [e.clientX, e.clientY]; cv.setPointerCapture(e.pointerId); };
  cv.onpointermove = e => { if (!drag) return; S.yaw += (e.clientX - drag[0]) * 0.01; S.pitch = Math.max(-1.4, Math.min(1.4, S.pitch + (e.clientY - drag[1]) * 0.01)); drag = [e.clientX, e.clientY]; draw(); };
  cv.onpointerup = () => { drag = null; };
  all();
}
