const RES_CELLS = [['ca1-a', 'mpg141209_A (Migliore 2018)'], ['ca1-b', 'mpg141208_B (Migliore 2018)'], ['ca1-jarsky', 'Jarsky 2005 cell'], ['ca1-5038804', 'n5038804 (Duke–Southampton)'], ['pyr-nmo-163712', 'SEU–Allen mouse CA1 (diameters not measured)']];
function renderDendriticResonance() {
  document.title = 'Theta resonance in real dendrites · Real biology';
  const D = RES_DATA, V = D._validation, cells = RES_CELLS.filter(([id]) => D[id]);
  $('lesson').innerHTML = bioHead('Theta resonance in real CA1 dendrites', 'REAL BIOLOGY · NEURON · ' + cells.length + ' RECONSTRUCTED CA1 CELLS · NARAYANAN & JOHNSTON 2007 H-CHANNEL GRADIENT', 'CA1 pyramidal dendrites prefer theta-range inputs, and the preferred frequency rises with distance from the soma because h channels get denser. This page takes a published, data-tuned h-channel model, checks it against the authors’ own output, then runs it on five other real CA1 cells to see how much of the resonance map comes from the h-channel gradient and how much from morphology.')
    + `<nav class="page-jumps"><a href="#res-map">Resonance map</a><a href="#res-z">Impedance curves</a><a href="#res-valid">Validation</a><a href="#res-uth">Model details</a><a href="#res-research">For your project</a><a href="/topics/ca1-resonance/impedance-phase/">Resonance lessons →</a></nav>
    <section class="lesson-section lab" id="res-map"><p class="eyebrow">01 · Compare with data</p><h2>Resonance frequency along the trunk</h2>
      <p>Each line is one real cell: the resonance frequency f<sub>R</sub> (the peak of |Z(f)|) measured with a local chirp current at points along the apical trunk, plotted against straight-line distance from the soma. Squares are recordings from Narayanan & Johnston (2007) at −65 mV: about 3 Hz at the soma and about 9 Hz at 300 µm.</p>
      <div class="nv-wrap"><canvas id="resMap" class="nv-canvas" style="height:340px" aria-label="Resonance frequency versus distance"></canvas>
      <div class="lab-controls"><div class="control-row"><label>h-channel density</label><div class="lab-actions ml-seg">${[['0.5', '0.5×'], ['1.0', '1×'], ['1.5', '1.5×'], ['norm', '1×, distance-normalised']].map(([k, l]) => `<button class="secondary" data-rk="${k}" aria-pressed="${k === '1.0'}">${l}</button>`).join('')}</div></div>
        <div class="control-row"><label>Show</label><div class="lab-actions ml-seg"><button class="secondary" data-rv="fR" aria-pressed="true">f<sub>R</sub></button><button class="secondary" data-rv="Q">Q</button><button class="secondary" data-rv="Zmax">|Z|<sub>max</sub></button></div></div>
        <div id="resKey" class="uth-key"></div></div></div><div id="resOut" class="ml-tablewrap"></div></section>
    <section class="lesson-section lab" id="res-z"><p class="eyebrow">02 · Look closer</p><h2>Impedance curves for one cell</h2>
      <div class="nv-wrap"><canvas id="resZ" class="nv-canvas" style="height:320px" aria-label="Impedance amplitude versus frequency at several distances"></canvas>
      <div class="lab-controls"><div class="control-row"><label for="resCell">Cell</label><select id="resCell">${cells.map(([id, l]) => `<option value="${id}">${l}</option>`).join('')}</select></div><div id="resZOut" class="ml-fp"></div>
      <p class="muted">Each curve is |Z(f)| at one trunk location (darker = farther from the soma). The peak moves to higher frequency and the curve flattens distally, where the h conductance and the membrane leak are largest.</p></div></div></section>
    <section class="lesson-section" id="res-valid"><p class="eyebrow">03 · Behind the black box</p><h2>Does the pipeline reproduce the published model?</h2>
      <p>I ran the authors’ cell (ModelDB 147578, neuron n123) unchanged and measured it with this page’s chirp + FFT code, then compared against the values they distribute (<code>Trunk_Z.txt</code>):</p>
      <div class="ml-tablewrap"><table class="gf-tab"><tr><th>Distance</th><th>f<sub>R</sub> this pipeline</th><th>f<sub>R</sub> authors</th><th>Q this / authors</th><th>|Z|<sub>max</sub> this / authors (MΩ)</th></tr>${V.map(r => `<tr><td>${r[0]} µm</td><td>${r[1].toFixed(2)} Hz</td><td>${r[4].toFixed(2)} Hz</td><td>${r[2].toFixed(3)} / ${r[5].toFixed(3)}</td><td>${r[3].toFixed(1)} / ${r[6].toFixed(1)}</td></tr>`).join('')}</table></div>
      <p class="uth-now">|Z|<sub>max</sub> agrees within about 1% and Q within about 0.02. f<sub>R</sub> agrees within about 0.3 Hz up to 350 µm and 0.7 Hz at 407 µm, where the original chirp (0–25 Hz over 25 s) samples high frequencies more finely than this one (0.5–20 Hz over 9.6 s). Curves are smoothed over 1.25 Hz before the peak is located (with parabolic interpolation), which is why f<sub>R</sub> now tracks the authors' values within about 0.3 Hz up to 350 µm.</p></section>
    <section class="lesson-section" id="res-uth"><p class="eyebrow">04 · Model details</p><h2>Under the hood</h2>
      <details class="uth" open><summary><span>Under the hood</span> channel, gradients, how the trunk is found, protocol</summary><div class="uth-grid">
        <section><h4>Membrane</h4><p>\\(C_m\\dot V=-g_{pas}(V-E_{pas})-\\bar g_h\\,l\\,(V-E_h)+I_{chirp}\\), with \\(\\tau_l(V)\\dot l=l_\\infty(V)-l\\) (Magee-type h kinetics from the authors’ <code>h.mod</code>, q10 = 4.5, 34 °C, E<sub>h</sub> = −30 mV). E<sub>pas</sub> is set per segment so that −65 mV is the steady state.</p></section>
        <section><h4>Gradients (d = straight-line distance from the soma)</h4><ul class="skill-tips"><li>\\(\\bar g_h(d)=34\\,\\mu S/cm^2\\,\\left(1+\\frac{100}{1+e^{-(d-380)/34}}\\right)\\) on the trunk</li><li>V<sub>½</sub>: −82 mV up to 100 µm, then falling linearly to −90 mV at 300 µm</li><li>R<sub>m</sub> = 200 kΩ·cm² falling sigmoidally to 12 kΩ·cm² (midpoint 200 µm); R<sub>a</sub> 50 → 35 Ω·cm</li><li>Obliques inherit the trunk values at their branch point; soma and basal dendrites use the base values.</li></ul></section>
        <section><h4>Finding the trunk in a new cell</h4><p>Start at the apical root section with the most dendrite below it, then repeatedly step into the child branch with the largest total subtree length until reaching a tip. This follows the main shaft into the tuft, as the hand-picked trunk does in the original model.</p></section>
        <section><h4>Protocol</h4><p>Linear chirp 0.5 → 20 Hz over 9.6 s, 20 pA, injected and recorded at the same location (local impedance). \\(|Z(f)|=|\\mathcal F\\{V\\}/\\mathcal F\\{I\\}|\\), averaged in 0.25 Hz bins. f<sub>R</sub> is the frequency at peak |Z|, Q = |Z(f<sub>R</sub>)| / |Z(0.5 Hz)|. Fixed step 0.1 ms.</p></section>
        <section><h4>Limits</h4><p>The gradients were tuned to the authors’ cell, so on other cells they are a hypothesis. There is no M-current (which supports somatic resonance near −60 mV; Hu et al. 2002) and no spines. Diameters of the SEU–Allen cell are not measured (constant), so its curve reflects branching only.</p></section></div></details></section>
    <section class="lesson-section" id="res-research"><p class="eyebrow">05 · For your CA1 resonance project</p><h2>What this lets you test</h2>
      <ul class="skill-tips"><li><b>Main finding: the published gradient does not transfer as-is.</b> With identical gradients, somatic f<sub>R</sub> ranges from about 4 Hz (n5038804) to about 9 Hz (the long Jarsky cell), against about 3 Hz in recordings. The gradient is defined in absolute µm, so longer cells place much more of their membrane in the high-h region, and that extra h current loads the soma.</li>
      <li><b>Normalising distance doesn't fix it:</b> rescaling each trunk to the original cell's length brings the soma down to about 3–5 Hz, but then the distal rise disappears (about 4 Hz at 300 µm instead of about 9 Hz). Neither rule reproduces the data across cells. The h-channel distribution has to be <b>fitted per cell</b>, or defined by something other than distance (for example dendritic diameter or branch order). This is a concrete, testable question for your project.</li>
      <li><b>Morphology vs channels:</b> any AD-vs-control comparison of resonance needs matched morphology or per-cell fits. Otherwise cell size alone can shift f<sub>R</sub> by several Hz.</li>
      <li><b>AD-like h-channel loss (0.5×) or LTP-like gain (1.5×):</b> Narayanan & Johnston showed that LTP increases h current and raises f<sub>R</sub> across the dendritic tree. Toggle the density to see the predicted shift in every cell.</li>
      <li><b>Link to your two-compartment model:</b> fit your soma/dendrite compartments to the 0 µm and 300 µm curves of one cell here. This turns the reduced model into one with measured spatial anchors.</li>
      <li><b>Next experiment in silico:</b> add the M-current at the soma and repeat at −60 mV, where the two resonance mechanisms (h and M) separate (Hu et al. 2002).</li></ul></section>
    <section class="lesson-section" id="code"><p class="eyebrow">06 · Do it in Python</p><h2>Measure impedance with a chirp</h2><div class="code-toolbar"><span>Python 3 · neuron</span></div><pre><code># Uses h.mod from ModelDB 147578 (git clone https://github.com/ModelDBRepository/147578; nrnivmodl .)
import numpy as np
from neuron import h
h.load_file("stdrun.hoc"); h.celsius = 34
s = h.Section(name="dend"); s.L, s.diam, s.nseg = 100, 2, 5
s.insert("pas"); s.cm, s.g_pas = 1, 1 / 20000
s.insert("hd"); s.ghdbar_hd, s.vhalfl_hd = 0.0005, -90; h.ehd_hd = -30
T, DT, F0, F1, AMP = 10000.0, 0.1, 0.5, 20.0, 0.02
t = np.arange(0, T, DT); tt = np.clip((t - 200) / 1000, 0, None); dur = (T - 400) / 1000
I = np.where((t >= 200) & (t <= T - 200), AMP * np.sin(2 * np.pi * (F0 * tt + (F1 - F0) / (2 * dur) * tt ** 2)), 0)
ic = h.IClamp(s(0.5)); ic.dur = 1e9; iv, tv = h.Vector(I), h.Vector(t); iv.play(ic._ref_amp, tv, 1)
v = h.Vector().record(s(0.5)._ref_v); h.dt = DT
h.finitialize(-65); h.fcurrent()
for seg in s: seg.e_pas = seg.v + seg.i_hd / seg.g_pas      # make −65 mV the resting state
h.finitialize(-65); h.continuerun(T)
v = np.array(v)[:len(t)]; m = (t >= 200) & (t <= T - 200)
Z = np.abs(np.fft.rfft(v[m] - v[m].mean()) / np.fft.rfft(I[m])); f = np.fft.rfftfreq(m.sum(), DT / 1000)
sel = (f > F0) & (f < F1); k = np.argmax(Z[sel])
print(f"resonance at {f[sel][k]:.2f} Hz, Q = {Z[sel][k] / Z[sel][0]:.2f}")</code></pre>
      <p class="muted">The notebook <b>“Dendritic resonance”</b> re-runs the published cell for validation and ports the gradients onto any SWC.</p></section>
    <section class="lesson-section reading"><p class="eyebrow">Sources</p><ol class="gf-refs">
      <li><a href="https://pmc.ncbi.nlm.nih.gov/articles/PMC2430016/" target="_blank" rel="noopener">Narayanan R, Johnston D (2007) Long-term potentiation in rat hippocampal neurons is accompanied by spatially widespread changes in intrinsic oscillatory dynamics and excitability. Neuron 56:1061–1075 ↗</a></li>
      <li><a href="https://modeldb.science/147578" target="_blank" rel="noopener">ModelDB 147578: chirp stimulus responses in a morphologically realistic model (Narayanan & Johnston 2007) ↗</a></li>
      <li><a href="https://pubmed.ncbi.nlm.nih.gov/?term=Two+forms+of+electrical+resonance+at+theta+frequencies+generated+by+M-current%2C+h-current+and+persistent+Na%2B+current" target="_blank" rel="noopener">Hu H, Vervaeke K, Storm JF (2002) Two forms of electrical resonance at theta frequencies, generated by M-current, h-current and persistent Na⁺ current in rat hippocampal pyramidal cells. J Physiol 545:783–805 ↗</a></li>
      <li><a href="https://pubmed.ncbi.nlm.nih.gov/?term=Dendritic+hyperpolarization-activated+currents+modify+the+integrative+properties+of+hippocampal+CA1+pyramidal+neurons" target="_blank" rel="noopener">Magee JC (1998) Dendritic hyperpolarization-activated currents modify the integrative properties of hippocampal CA1 pyramidal neurons. J Neurosci 18:7613–7624 ↗</a></li></ol></section>`;
  typeset(); resInit(D, cells);
}
function resInit(D, cells) {
  const S = { k: '1.0', v: 'fR', cell: cells[0][0] };
  const lab = { fR: ['resonance frequency f_R (Hz)', 0, 20], Q: ['resonance strength Q', 1, 1.6], Zmax: ['|Z|max (MΩ)', 0, 180] };
  const map = () => {
    const [x, W, H] = gfCanvas('resMap'), L = 48, B = H - 34, T = 10, Rr = W - 12, [yl, y0, y1] = lab[S.v], X = d => L + (Rr - L) * d / 420, Y = v => B - (B - T) * (v - y0) / (y1 - y0);
    x.strokeStyle = '#e6d8c8'; x.font = '11px system-ui'; for (let k = 0; k <= 4; k++) { const v = y0 + k * (y1 - y0) / 4, y = Y(v); x.beginPath(); x.moveTo(L, y); x.lineTo(Rr, y); x.stroke(); x.fillStyle = '#6f4c27'; x.fillText(+v.toFixed(2), 4, y + 4); }
    for (let d = 0; d <= 400; d += 100) x.fillText(d, X(d) - 8, H - 18); x.fillText('distance from soma (µm) · ' + yl, L, H - 3);
    cells.forEach(([id], i) => { const s = D[id][S.k].sites; x.strokeStyle = BAP_LCOL[i]; x.fillStyle = BAP_LCOL[i]; x.lineWidth = 2; x.beginPath(); s.forEach((p, j) => { const xx = X(p.d), yy = Y(p[S.v]); j ? x.lineTo(xx, yy) : x.moveTo(xx, yy); }); x.stroke(); s.forEach(p => { x.beginPath(); x.arc(X(p.d), Y(p[S.v]), 2.5, 0, 7); x.fill(); }); });
    x.lineWidth = 1;
    if (S.v === 'fR') { x.fillStyle = '#141111'; [[0, 3], [300, 9]].forEach(([d, f]) => x.fillRect(X(d) - 5, Y(f) - 5, 10, 10)); x.fillText('■ recordings, −65 mV', Rr - 130, T + 12);
      x.strokeStyle = '#141111'; x.setLineDash([3, 3]); x.beginPath(); D._nj.forEach((p, j) => { const xx = X(p[0]), yy = Y(p[1]); j ? x.lineTo(xx, yy) : x.moveTo(xx, yy); }); x.stroke(); x.setLineDash([]); x.fillText('- - published model cell (n123)', Rr - 170, T + 26); }
    $('resKey').innerHTML = cells.map(([id, l], i) => `<span><i style="background:${BAP_LCOL[i]}"></i>${l}</span>`).join('');
    const row = id => { const s = D[id][S.k].sites, a = s[0], b = s.reduce((p, q) => Math.abs(q.d - 300) < Math.abs(p.d - 300) ? q : p); return [a, b]; };
    $('resOut').innerHTML = `<table class="ml-table"><tr><th>Cell</th><th>soma f<sub>R</sub></th><th>~300 µm f<sub>R</sub></th><th>soma |Z|max</th></tr>${cells.map(([id, l]) => { const [a, b] = row(id); return `<tr><td>${l}</td><td>${a.fR.toFixed(1)} Hz</td><td>${b.fR.toFixed(1)} Hz <small>(${Math.round(b.d)} µm)</small></td><td>${a.Zmax} MΩ</td></tr>`; }).join('')}</table>`;
  };
  const zplot = () => {
    const s = D[S.cell][S.k].sites, [x, W, H] = gfCanvas('resZ'), L = 48, B = H - 34, T = 10, Rr = W - 12, zmax = Math.max(...s.flatMap(p => p.Z)) * 1.05, lx = f => Math.log(f / 0.5) / Math.log(40), X = f => L + (Rr - L) * lx(f), Y = z => B - (B - T) * z / zmax;
    x.strokeStyle = '#e6d8c8'; x.font = '11px system-ui'; [0.5, 1, 2, 5, 10, 20].forEach(f => { x.beginPath(); x.moveTo(X(f), T); x.lineTo(X(f), B); x.stroke(); x.fillStyle = '#6f4c27'; x.fillText(f + ' Hz', Math.min(X(f) - 10, Rr - 34), H - 18); }); x.fillText('frequency (log) · |Z| (MΩ)', L, H - 3);
    for (let k = 0; k <= 4; k++) { const z = zmax * k / 4; x.fillText(Math.round(z), 4, Y(z) + 4); }
    const F = D._f; s.forEach((p, j) => { const c = Math.round(30 + 50 * j / Math.max(1, s.length - 1)); x.strokeStyle = `hsl(330 60% ${80 - c * 0.6}%)`; x.lineWidth = 2; x.beginPath(); F.forEach((f, i) => { const xx = X(f), yy = Y(p.Z[i]); i ? x.lineTo(xx, yy) : x.moveTo(xx, yy); }); x.stroke(); x.fillStyle = x.strokeStyle; const k = p.Z.indexOf(Math.max(...p.Z)); x.beginPath(); x.arc(X(F[k]), Y(p.Z[k]), 3, 0, 7); x.fill(); });
    x.lineWidth = 1; $('resZOut').innerHTML = s.map(p => `${Math.round(p.d)} µm: f<sub>R</sub> ${p.fR.toFixed(1)} Hz, Q ${p.Q.toFixed(2)}`).join('<br>');
  };
  document.querySelectorAll('[data-rk]').forEach(b => b.onclick = () => { S.k = b.dataset.rk; document.querySelectorAll('[data-rk]').forEach(o => o.setAttribute('aria-pressed', o === b)); map(); zplot(); });
  document.querySelectorAll('[data-rv]').forEach(b => b.onclick = () => { S.v = b.dataset.rv; document.querySelectorAll('[data-rv]').forEach(o => o.setAttribute('aria-pressed', o === b)); map(); });
  $('resCell').onchange = e => { S.cell = e.target.value; zplot(); };
  map(); zplot();
}
window.renderDendriticResonance = renderDendriticResonance;
/* NEURON twin files embedded for the Neuron lab export (generated from lab/twin by build.sh). */
const NG_TWIN_PY = "#!/usr/bin/env python3\n\"\"\"Reproduce a Little Neural Guide 'Neuron lab' run in NEURON.\n\nUsage (inside the unzipped export folder):\n    pip install neuron numpy matplotlib\n    git clone --depth 1 https://github.com/ModelDBRepository/55035 mdb55035     # Migliore et al. 2005 channels\n    mkdir -p mech && cp mdb55035/{h,kadist,kaprox,kdrca1,na3n,naxn,distr}.mod nmda_js.mod mech/ && (cd mech && nrnivmodl .)\n    python neuron_twin.py                      # reads config.json + morphology.json, writes neuron_traces.csv and compare.png\n\nThe channel model, toggles, branch blocks, cuts, leak-reversal rule and synapse kinetics match the browser engine (ngCable).\nChecked against the browser on CA1 cells: \u2264 1.2 mV RMSE in bAP profiles across 17 of 18 toggle conditions (see the page's Under the hood).\n\"\"\"\nimport copy, csv, json, math, os, sys\nimport numpy as np\nfrom neuron import h\n\nfor p in ('mech/x86_64/libnrnmech.so', 'mech/arm64/libnrnmech.dylib', 'mech/x86_64/.libs/libnrnmech.so', 'mech/arm64/.libs/libnrnmech.so', 'x86_64/libnrnmech.so', 'arm64/libnrnmech.dylib'):\n    if os.path.exists(p) and not hasattr(h, 'na3'): h.nrn_load_dll(os.path.abspath(p))\nif not hasattr(h, 'na3'): sys.exit('Compile the mechanisms first (see the usage notes at the top of this file).')\nh.load_file('stdrun.hoc')\n\nDEFAULT = dict(Rm=28000, Cm=1, Ra=150, RaAx=50, celsius=35, gna=0.025, axonm=5, gkdr=0.01, gka=0.03, ghd=0.00005, Ena=55, Ek=-90, Eh=-30, Vrest=-65,\n               on=dict(na=True, kdr=True, ka=True, h=True), scale=dict(na=1, kdr=1, ka=1, h=1),\n               regions=dict(soma=True, basal=True, apical=True, axon=True), gradients=dict(ka=True, h=True), spine=dict(on=False, F=2))\nSYN = {'ampa': (0.2, 2, 0), 'nmda': (2, 50, 0), 'gaba': (0.5, 8, -75), 'gabab': (30, 150, -90)}   # tau1, tau2 (ms), E (mV): same as the browser\n\n\ndef merge(bio):\n    b = copy.deepcopy(DEFAULT)\n    for k, v in (bio or {}).items():\n        if isinstance(v, dict): b[k].update(v)\n        else: b[k] = v\n    return b\n\n\ndef subtree(sections, s):\n    kids = [[] for _ in sections]\n    for i, sec in enumerate(sections):\n        if sec[1] >= 0: kids[sec[1]].append(i)\n    out = [s]; k = 0\n    while k < len(out): out += kids[out[k]]; k += 1\n    return out\n\n\ndef build(cell, gone=()):\n    \"\"\"Sections from [type, parent, flat xyz, radii]; soma = cylinder with the traced soma's area. Returns soma, {orig index: Section}, kinds.\"\"\"\n    soma = h.Section(name='soma'); poly = np.array(cell['soma']).reshape(-1, 2)\n    area = 0.5 * abs(np.dot(poly[:, 0], np.roll(poly[:, 1], 1)) - np.dot(poly[:, 1], np.roll(poly[:, 0], 1))) if len(poly) >= 3 else 100\n    d = max(8.0, 2 * math.sqrt(area / math.pi)); soma.L = soma.diam = d\n    secs, kinds = {}, {}\n    for i, (t, par, xyz, r) in enumerate(cell['sections']):\n        if i in gone: continue\n        s = h.Section(name=f'sec{i}'); pts = np.array(xyz).reshape(-1, 3); r = list(r)\n        if par >= 0: p = cell['sections'][par][2]; pts = np.vstack([p[-3:], pts]); r = [r[0]] + r\n        if len(pts) < 2 or np.ptp(pts, axis=0).max() < 1e-6: pts = np.vstack([pts[:1], pts[:1] + [0, 0.05, 0]]); r = [r[0], r[0]]\n        for (x, y, z), rr in zip(pts, r): h.pt3dadd(x, y, z, max(0.2, 2 * rr), sec=s)\n        s.connect(secs[par](1)) if par >= 0 else s.connect(soma(0.5))\n        secs[i] = s; kinds[i] = t\n    return soma, secs, kinds\n\n\ndef setup(cell, bio=None, marks=(), clear=True):\n    if clear: h('forall delete_section()')\n    b = merge(bio); cuts = [m['sec'] for m in marks if m['kind'] == 'cut']\n    gone = set(i for c in cuts for i in subtree(cell['sections'], c))\n    soma, secs, kinds = build(cell, gone); h.celsius = b['celsius']\n    blocked = {}\n    for m in marks:\n        if m['kind'] in ('ttx', 'noka', 'noh', 'passive'):\n            for o in subtree(cell['sections'], m['sec']): blocked.setdefault(o, set()).add(m['kind'])\n    allsec = [(soma, 1, set())] + [(s, kinds[i], blocked.get(i, set())) for i, s in secs.items()]\n    for s, k, _ in allsec:\n        s.insert('pas'); s.g_pas = 1 / b['Rm']; s.e_pas = b['Vrest']; s.cm = b['Cm']; s.Ra = b['Ra']\n        s.nseg = int((s.L / (0.1 * h.lambda_f(50, sec=s)) + 0.9) / 2) * 2 + 1 if s.L > 1e-3 else 1\n    h.distance(0, 0.5, sec=soma)\n    on, sc, rg, gr = b['on'], b['scale'], b['regions'], b['gradients']\n    for s, k, blk in allsec:\n        reg = {1: 'soma', 2: 'axon', 4: 'apical'}.get(k, 'basal'); a = rg[reg]\n        u = dict(na=a and on['na'] and not blk & {'ttx', 'passive'}, kdr=a and on['kdr'] and 'passive' not in blk,\n                 ka=a and on['ka'] and not blk & {'noka', 'passive'}, h=a and on['h'] and not blk & {'noh', 'passive'} and reg != 'axon')\n        s.insert('ds')\n        if reg == 'axon': s.Ra = b['RaAx']\n        if u['na']: s.insert('nax' if reg == 'axon' else 'na3')\n        if u['kdr']: s.insert('kdr')\n        if u['ka']:\n            s.insert('kap')\n            if reg not in ('soma', 'axon'): s.insert('kad')\n        if u['h']: s.insert('hd')\n        last = 0\n        for seg in s:\n            dd = h.distance(seg.x, sec=s) if reg != 'soma' else 0; last = dd\n            if u['na']:\n                if reg == 'axon': seg.gbar_nax = b['gna'] * b['axonm'] * sc['na']\n                else: seg.gbar_na3 = b['gna'] * sc['na']\n            if u['kdr']: seg.gkdrbar_kdr = b['gkdr'] * sc['kdr']\n            if u['ka']:\n                g = b['gka'] * sc['ka'] * ((1 + dd / 100) if gr['ka'] and reg not in ('soma', 'axon') else 1)\n                if reg in ('soma', 'axon') or dd <= 100:\n                    seg.gkabar_kap = g\n                    if reg not in ('soma', 'axon'): seg.gkabar_kad = 0\n                else: seg.gkabar_kap = 0; seg.gkabar_kad = g\n            if u['h']: seg.ghdbar_hd = b['ghd'] * sc['h'] * ((1 + 3 * dd / 100) if gr['h'] and reg != 'soma' else 1)\n        if u['h']: s.vhalfl_hd = -81 if reg != 'soma' and last > 100 else -73\n        if b['spine']['on'] and reg in ('basal', 'apical'):   # spine area correction beyond 100 \u00b5m, as in the browser\n            for seg in s:\n                if h.distance(seg.x, sec=s) > 100: seg.cm *= b['spine']['F']; seg.g_pas *= b['spine']['F']\n    return soma, secs, b\n\n\ndef init(b):\n    \"\"\"Leak reversal per segment so that Vrest is a steady state with every active current (same rule as the browser).\"\"\"\n    for s in h.allsec():\n        if h.ismembrane('na3', sec=s) or h.ismembrane('nax', sec=s): s.ena = b['Ena']\n        if h.ismembrane('kdr', sec=s) or h.ismembrane('kap', sec=s): s.ek = b['Ek']\n    h.ehd_hd = b['Eh']; h.finitialize(b['Vrest']); h.fcurrent()\n    for s in h.allsec():\n        for seg in s:\n            i = 0\n            if h.ismembrane('na3', sec=s) or h.ismembrane('nax', sec=s): i += seg.ina\n            if h.ismembrane('kdr', sec=s) or h.ismembrane('kap', sec=s): i += seg.ik\n            if h.ismembrane('hd', sec=s): i += seg.i_hd\n            seg.e_pas = b['Vrest'] + i / seg.g_pas\n    h.finitialize(b['Vrest'])\n\n\ndef loc(soma, secs, sec, f):\n    if sec is None or sec < 0: return soma(0.5)\n    return secs[sec](min(max(f, 0.0), 1.0)) if sec in secs else None\n\n\ndef stim_windows(st, tstop):\n    w = []\n    if st['kind'] == 'step': w.append((st['t0'], st['dur']))\n    elif st['kind'] == 'train':\n        for k in range(int(st.get('np', 1))): w.append((st['t0'] + k * 1000 / st['freq'], min(st['dur'], 1000 / st['freq'] * 0.8)))\n    elif st['kind'] == 'tbs':\n        for bb in range(4):\n            for k in range(4): w.append((st['t0'] + bb * 200 + k * 10, 2))\n    return [(a, d) for a, d in w if a < tstop]\n\n\nLAST = {}   # sections of the most recent run (Python-created sections disappear when unreferenced)\n\n\ndef run(cfg, cell):\n    soma, secs, b = setup(cell, cfg['bio'], cfg.get('marks', []))\n    LAST.clear(); LAST.update(soma=soma, secs=secs, bio=b)\n    keep = []\n    for a, d in stim_windows(cfg['stim'], cfg['tstop']):\n        ic = h.IClamp(soma(0.5)); ic.delay, ic.dur, ic.amp = a, d, cfg['stim']['amp']; keep.append(ic)\n    for s in cfg.get('syns', []):\n        seg = loc(soma, secs, s.get('sec'), s.get('f', 0.5))\n        if seg is None: continue\n        for ty, w in ([('ampa', s['w']), ('nmda', s['w'] * 0.8)] if s['type'] == 'ampanmda' else [(s['type'], s['w'])]):\n            t1, t2, e = SYN[ty]\n            if ty == 'nmda': syn = h.NMDA_JS(seg)                       # Exp2 kinetics \u00d7 Jahr\u2013Stevens Mg\u00b2\u207a block, 1 mM\n            else: syn = h.Exp2Syn(seg)\n            syn.tau1, syn.tau2, syn.e = t1, t2, e\n            nc = h.NetCon(None, syn); nc.weight[0] = w * 1e-3        # nS \u2192 \u00b5S\n            keep += [syn, nc]\n            for j in range(int(s.get('n', 1))): keep.append((nc, s['t0'] + j * s.get('isi', 0)))\n    probes = [soma(0.5)] + [loc(soma, secs, p['sec'], p['f']) for p in cfg.get('probes', [])]\n    recs = [h.Vector().record(p._ref_v) if p is not None else None for p in probes]; tv = h.Vector().record(h._ref_t)\n    h.dt = 0.025; h.tstop = cfg['tstop']; init(b)\n    for item in keep:\n        if isinstance(item, tuple): item[0].event(item[1])\n    h.continuerun(cfg['tstop'])\n    return np.array(tv), [np.array(r) if r is not None else None for r in recs]\n\n\nif __name__ == '__main__':\n    cfg = json.load(open('config.json')); cell = json.load(open('morphology.json'))\n    t, vs = run(cfg, cell)\n    names = ['soma'] + [f\"P{i + 1} {p['label']}\" for i, p in enumerate(cfg.get('probes', []))]\n    with open('neuron_traces.csv', 'w', newline='') as f:\n        w = csv.writer(f); w.writerow(['t_ms'] + names)\n        for k in range(len(t)): w.writerow([round(t[k], 4)] + [round(v[k], 4) if v is not None else '' for v in vs])\n    sp = int(np.sum((vs[0][:-1] < 0) & (vs[0][1:] >= 0)))\n    print(f'NEURON: {sp} somatic spikes, soma peak {vs[0].max():.1f} mV, written neuron_traces.csv')\n    if os.path.exists('traces.csv'):   # compare with the browser run\n        import matplotlib; matplotlib.use('Agg'); import matplotlib.pyplot as plt\n        B = np.genfromtxt('traces.csv', delimiter=',', names=True)\n        plt.figure(figsize=(7, 3.4)); plt.plot(B['t_ms'], B[B.dtype.names[1]], 'k', lw=2, label='browser (ngCable) soma')\n        plt.plot(t, vs[0], 'r--', lw=1.4, label='NEURON soma'); plt.xlabel('ms'); plt.ylabel('mV'); plt.legend(frameon=False); plt.tight_layout(); plt.savefig('compare.png', dpi=150)\n        bv = B[B.dtype.names[1]]; st = lambda tt, v: tt[1:][(v[:-1] < 0) & (v[1:] >= 0)]\n        sb, sn = st(B['t_ms'], bv), st(t, vs[0]); print('spike times browser:', np.round(sb, 2).tolist()); print('spike times NEURON: ', np.round(sn, 2).tolist())\n        if len(sb) > 1 and len(sn) > 1: print(f'mean ISI browser {np.diff(sb).mean():.2f} ms vs NEURON {np.diff(sn).mean():.2f} ms ({100 * (np.diff(sb).mean() / np.diff(sn).mean() - 1):+.1f} %)')\n        print('wrote compare.png')\n";
const NG_NMDA_MOD = ": Double-exponential NMDA synapse with Jahr & Stevens (1990) Mg2+ block, [Mg2+] = 1 mM.\n: Same kinetics as the Little Neural Guide browser engine (tau1 = 2 ms, tau2 = 50 ms, E = 0 mV).\nNEURON {\n  POINT_PROCESS NMDA_JS\n  RANGE tau1, tau2, e, i, g, mg\n  NONSPECIFIC_CURRENT i\n}\nUNITS { (nA) = (nanoamp) (mV) = (millivolt) (uS) = (microsiemens) (mM) = (milli/liter) }\nPARAMETER { tau1 = 2 (ms) tau2 = 50 (ms) e = 0 (mV) mg = 1 (mM) }\nASSIGNED { v (mV) i (nA) g (uS) factor }\nSTATE { A (uS) B (uS) }\nINITIAL {\n  LOCAL tp\n  if (tau1/tau2 > 0.9999) { tau1 = 0.9999*tau2 }\n  A = 0  B = 0\n  tp = (tau1*tau2)/(tau2 - tau1) * log(tau2/tau1)\n  factor = 1/(-exp(-tp/tau1) + exp(-tp/tau2))\n}\nBREAKPOINT {\n  SOLVE state METHOD cnexp\n  g = (B - A) / (1 + exp(-0.062*v) * mg/3.57)\n  i = g*(v - e)\n}\nDERIVATIVE state { A' = -A/tau1  B' = -B/tau2 }\nNET_RECEIVE(weight (uS)) { A = A + weight*factor  B = B + weight*factor }\n";
