const ngPlaus = (key, v) => { const r = NG_RANGE[key]; if (!r) return null; return { ok: v >= r[0] && v <= r[1], txt: `${v < r[0] || v > r[1] ? 'Outside' : 'Within'} the typical range ${r[0]}–${r[1]}. ${r[2]}` }; };
/** Mark an <output> with a plausibility badge. */
function ngBadge(out, key, v) { const p = ngPlaus(key, v); if (!out || !p) return; out.classList.toggle('ng-warn', !p.ok); out.title = p.txt; }
