  const cv = $('cbCv'); let anim = 0, token = 0, layout = null;
  const M = id => cells.find(m => m.id === id);
  const short = (c, i) => `${i + 1}. ${M(c.id).short || M(c.id).name.replace(/ \(.*\)/, '')}`;
  const label = short;
  const col = i => CB_CCOL[i % CB_CCOL.length];
  const isInh = ty => /gaba|glycine/.test(ty);
