  /* ---------- tabs ---------- */
  const tab = name => { document.querySelectorAll('#cb-lab [data-tab]').forEach(b => b.setAttribute('aria-selected', b.dataset.tab === name)); document.querySelectorAll('#cb-lab [data-pane]').forEach(p => p.hidden = p.dataset.pane !== name); };
  document.querySelectorAll('#cb-lab [data-tab]').forEach(b => b.onclick = () => tab(b.dataset.tab));
  /* ---------- cell cards ---------- */
