    $('cbNc').textContent = S.cells.length; $('cbNk').textContent = S.cons.length + S.gaps.length;
    $('cbAddB').disabled = S.cells.length >= 8; $('cbAddNote').textContent = S.cells.length >= 8 ? 'The circuit is full (8 cells). Remove one to add another.' : 'Up to 8 cells. Interneurons get the interneuron-like channel profile automatically.';
    $('cbCells').innerHTML = S.cells.length ? S.cells.map((c, i) => { const d = c.drive; return `<div class="ux-card" style="--c:${col(i)}"><div class="ux-ch"><b>${short(c, i)}</b><span class="muted">${M(c.id).code}</span><button class="ux-x" data-cbdel="${i}" aria-label="Remove cell ${i + 1}">×</button></div>
      ${cbF('Channels', `<select data-cbprof="${i}">${Object.entries(CB_PROFILES).map(([k, [l]]) => `<option value="${k}" ${k === c.prof ? 'selected' : ''}>${l.split(' (')[0]}</option>`).join('')}</select>`)}
      <div class="ux-seg" role="radiogroup" aria-label="Input to cell ${i + 1}">${[['none', 'No input'], ['step', 'Current step'], ['poisson', 'Poisson synapses']].map(([k, l]) => `<button role="radio" aria-checked="${d.kind === k}" data-cbdk="${i}:${k}">${l}</button>`).join('')}</div>
      ${d.kind === 'step' ? `<div class="ux-3">${[['amp', 'Amplitude', 0.05, 'nA'], ['t0', 'Start', 1, 'ms'], ['dur', 'Duration', 1, 'ms']].map(([k, l, st, u]) => cbF(l, `<input type="number" class="ux-num" step="${st}" value="${d[k]}" data-cbdv="${i}:${k}">`, u)).join('')}</div>` : ''}
      ${d.kind === 'poisson' ? `<div class="ux-2">${[['rate', 'Rate', 1, 'Hz'], ['n', 'Contacts', 1, ''], ['w', 'Per contact', 0.1, 'nS'], ['dur', 'Duration', 1, 'ms']].map(([k, l, st, u]) => cbF(l, `<input type="number" class="ux-num" step="${st}" value="${d[k]}" data-cbdv="${i}:${k}">`, u)).join('')}</div>
        <div class="ux-2">${cbF('Where', `<select data-cbdv="${i}:region">${CB_REGIONS.map(([k, l]) => `<option value="${k}" ${k === d.region ? 'selected' : ''}>${l.split(' (')[0]}</option>`).join('')}</select>`)}${cbF('Receptor', `<select data-cbdv="${i}:type">${CB_TYPES.map(([k, l]) => `<option value="${k}" ${k === d.type ? 'selected' : ''}>${l.replace(/^.*· /, '')}</option>`).join('')}</select>`)}</div>` : ''}
      </div>`; }).join('') : '<p class="ux-empty">No cells yet. Pick a preset above or add a reconstruction below.</p>';
    /* connection cards */
