    $('cbFrom').innerHTML = opts; $('cbTo').innerHTML = opts; if (fv !== '' && +fv < S.cells.length) $('cbFrom').value = fv; if (S.cells.length > 1) $('cbTo').value = tv !== '' && +tv < S.cells.length ? tv : 1;
