  document.querySelectorAll('[data-cbr]').forEach(c => c.oninput = c.onchange = e => { const k = c.dataset.cbr, v = clampTo(c, +c.value); if (e.type === 'change') c.value = v; S.run[k] = v; document.querySelectorAll(`[data-cbr="${k}"]`).forEach(x => { if (x !== c) x.value = v; }); if (k === 'tstop') { setStale(true); plots(); } if (k === 'detail' && e.type === 'change') changed(); });
  $('cbEdge').onchange = () => { const E = CB_EDGES[$('cbEdge').value]; edgeTxt(); if (E && E[1]) { const P = E[1]; $('cbTy').value = P.type; $('cbRg').value = P.region; setCon('n', P.n); setCon('w', P.w); setCon('d', P.d); S.con.stpOn = !!P.stp; if (P.stp) { setCon('U', P.stp.U); setCon('tf', P.stp.tf); setCon('td', P.stp.td); } } formSync(); };
  $('cbStp').onchange = e => { S.con.stpOn = e.target.checked; $('cbEdge').value = 'custom'; edgeTxt(); formSync(); };
