const MW_REC = [['ampa', 'Glutamate · AMPA'], ['ampanmda', 'Glutamate · AMPA + NMDA'], ['nmda', 'Glutamate · NMDA only'], ['kainate', 'Glutamate · kainate'], ['gaba', 'GABA · GABA-A (Cl⁻)'], ['gabab', 'GABA · GABA-B (K⁺, slow)'], ['nachr', 'Acetylcholine · nicotinic'], ['machr', 'Acetylcholine · muscarinic (closes K⁺)'], ['glycine', 'Glycine · GlyR (Cl⁻)']];
