const MW_COLOR = [['type', 'Neurite type'], ['dist', 'Path distance'], ['X0', 'Electrotonic distance (DC)'], ['Xf', 'Electrotonic distance (at f)'], ['order', 'Branch order'], ['diam', 'Diameter'], ['result', 'Current tab result']];

