      for (let i = 1; i < c.n; i++) { const p = c.par[i]; x.strokeStyle = V ? nlVcol(V[i]) : (c.kind[i] === 2 ? '#6f4c27' : '#a6795b'); x.lineWidth = Math.max(2, c.d[i] * 0.8); x.beginPath(); x.moveTo(cx + c.x[p] * 0.9, cy - c.y[p] * 0.9); x.lineTo(cx + c.x[i] * 0.9, cy - c.y[i] * 0.9); x.stroke(); }
