    const rr = Math.min(split, hv) * 0.42 * Math.tan(Math.min(a, 170) * Math.PI / 360) / Math.tan(85 * Math.PI / 180), azr = E.az * Math.PI / 180, dx = Math.sin(azr) * (split / 2 - 24) * (Math.abs(E.az) > 90 ? -1 : 1);
