    x.fillStyle = 'rgba(244,236,226,.85)'; x.fillRect(10, 10, 210, 20); x.fillStyle = '#6f4c27'; x.font = '12px system-ui'; x.fillText(`fly's view · ${a.toFixed(0)}° · ${Math.abs(E.az) > 90 ? 'rear field' : E.az > 0 ? 'right eye' : E.az < 0 ? 'left eye' : 'both eyes'}`, 14, 24);
    const ty0 = hv + 4, tcx = split / 2, tcy = ty0 + (h - ty0 - 8) / 2, ar = Math.min(split, h - ty0) * 0.38;
    x.fillStyle = '#fbf6ef'; x.fillRect(8, ty0, split - 16, h - ty0 - 8); x.strokeStyle = '#e6d8c8'; x.beginPath(); x.arc(tcx, tcy, ar, 0, 7); x.stroke();
    const sx = tcx + Math.sin(azr) * ar, sy = tcy - Math.cos(azr) * ar; x.fillStyle = '#141111'; x.beginPath(); x.arc(sx, sy, 4 + 10 * Math.min(1, a / 120), 0, 7); x.fill();
