    if (R) { const tn = R.take != null ? Math.min(t, R.take) : t, tDet = R.tAt(20), pp = tn > tDet ? 1 - Math.exp(-(tn - tDet) / E.postTau) : 0, aw = (E.az + 180) * Math.PI / 180;
      if (pp > 0.02) { x.strokeStyle = '#d08a2e'; x.lineWidth = 3; x.beginPath(); x.moveTo(tcx, tcy); x.lineTo(tcx + Math.sin(aw) * ar * 0.6 * pp, tcy - Math.cos(aw) * ar * 0.6 * pp); x.stroke(); }
      if (R.take != null && t >= R.take) { const d = R.dir * Math.PI / 180; x.strokeStyle = '#2f7d5b'; x.setLineDash([4, 3]); x.lineWidth = 2; x.beginPath(); x.moveTo(tcx, tcy); x.lineTo(tcx + Math.sin(d) * ar * 0.9, tcy - Math.cos(d) * ar * 0.9); x.stroke(); x.setLineDash([]); } }
