    x.fillStyle = '#6f4c27'; const step = (t1 - t0) > 400 ? 100 : (t1 - t0) > 150 ? 25 : 10; for (let t = Math.ceil(t0 / step) * step; t <= t1; t += step) x.fillText(t, X(t) - 8, H - 4);
